INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130596, 'spa', 'Siclag (nombre propio, ciudad en el Néguev)', 'Siclag (nombre propio, ciudad en el Néguev): El topónimo Siclag (צִקְלַג), que identifica una única ciudad del Néguev en la frontera entre Judá y Filistea. Las quince apariciones — con variantes ortográficas y preposicionales menores — se refieren todas a esta misma localidad. Su importancia narrativa se centra en el período de exilio de David: recibida de Aquis (1 Sam 27:6), saqueada por los amalecitas (1 Sam 30:1–26) y base de David cuando supo de la muerte de Saúl (2 Sam 1:1).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130603, 'spa', 'Saco o alforja', 'Probablemente se refiere a una bolsa, saco o alforja usada para transportar provisiones, como aparece en 2 Reyes 4:42, donde un hombre lleva primicias a Eliseo en dicho recipiente. Aunque el significado preciso del término es debatido, el contexto apoya entenderlo como un saco para alimentos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130604, 'spa', 'Estrecho, angosto, apretado', 'Adjetivo que describe estrechez, angostura o constricción física de un espacio. Se usa para un lugar angosto donde la burra de Balaam queda encerrada (Núm 22:26), una morada demasiado reducida para los hijos de los profetas (2 Re 6:1), un pozo profundo y estrecho como figura de la ramera (Prov 23:27), y las escamas fuertemente selladas del cocodrilo (Job 41:15).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130609, 'spa', 'Adversario, enemigo', 'Uso sustantivado como nombre que significa adversario, oponente o enemigo — aquel que constriñe u oprime. En Isaías 59:19 el צַר es el enemigo que viene como río desbordado, contra el cual el Espíritu del Señor levanta bandera. El alemán Bedränger («opresor») y el hindi shatru («enemigo») marcan claramente la lectura personal-adversativa, distinta del adjetivo espacial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130610, 'spa', 'La condición abstracta de angustia, aflicción o tribulación — estar en aprietos ', 'La condición abstracta de angustia, aflicción o tribulación — estar en aprietos o en un lugar estrecho. A menudo acompañado de preposiciones (''en angustia,'' ''de la angustia'') para describir circunstancias de tribulación desde las cuales se clama a Dios por liberación. El hindi ''sankat,'' el árabe ''diq'' y el suajili ''dhiki'' transmiten la metáfora de constricción. Pasajes clave: 2 Sam 22:7, Sal 32:7, Job 15:24, Isa 5:30.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130617, 'spa', 'Un adversario, oponente o enemigo hostil personal — el agente concreto de la ang', 'Un adversario, oponente o enemigo hostil personal — el agente concreto de la angustia, no el estado en sí. La evidencia multilingüe confirma esta distinción: el coreano usa ''daejeok'' (adversario) frente a ''hwannan'' (tribulación), y el hindi usa ''shatru/dushman'' (enemigo). En Sal 60:11 y 108:12, la súplica de ayuda divina ''del adversario'' identifica claramente a un enemigo personal, al igual que 1 Sam 2:32.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130627, 'spa', 'Adversario, enemigo', 'Adversario, enemigo: persona hostil, oponente o enemigo nacional que oprime o acosa a otro. A lo largo de 69 apariciones, las traducciones emplean de manera consistente términos como «adversario» o «enemigo». La victoria de Abraham entregó a sus enemigos en su mano (Gn 14:20), e Israel debía hacer sonar las trompetas contra el adversario que los oprimía (Nm 10:9).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130637, 'spa', 'Angustia, aflicción', 'Angustia, aflicción: estado de congoja, constricción o adversidad, la dimensión abstracta del significado de estrechez que posee la raíz. Aparece en unas 6 pasajes donde las traducciones oscilan entre lenguaje de adversario y de angustia. David eligió caer en la mano de Dios antes que enfrentar la angustia humana (2 S 24:14; 1 Cr 21:13).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130671, 'spa', 'Pedernal o sílex', 'Se refiere al pedernal o piedra extremadamente dura, usado en Isaías 5:28 para comparar la dureza de los cascos de los caballos invasores. El símil enfatiza la preparación y resistencia del enemigo: cascos duros como pedernal que no se desgastan ni se quiebran ni siquiera en largas campañas militares.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130672, 'spa', 'Ciudad de Neftalí', 'Nombre de una ciudad fortificada en el territorio de Neftalí, mencionada en Josué 19:35 entre los asentamientos fortificados asignados a esta tribu. Aunque su ubicación precisa se desconoce, su inclusión en la lista indica que era un centro urbano defendido de cierta relevancia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130674, 'spa', 'Nombre propio Tsor/Tsur, la ciudad costera fenicia famosa por su comercio maríti', 'Nombre propio Tsor/Tsur, la ciudad costera fenicia famosa por su comercio marítimo y su artesanía. Aparece como socio comercial de Israel bajo Hiram (2 Sam 5:11; 1 Re 5:1) y como blanco del juicio profético por su arrogancia (Am 1:9-10; Is 23; Ez 26-28). Denominada mivtsar-Tsor (''fortaleza de Tiro,'' 2 Sam 24:7). Atestiguada en asirio como Surru.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130681, 'spa', 'Ser abrasado', 'En la conjugación Nifal, significa ser abrasado o chamuscado. Se emplea en Ezequiel 20:47, donde el profeta declara juicio sobre la tierra: todos los rostros serán abrasados por el fuego divino que arrasará el territorio, afectando a todos desde el sur hasta el norte.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130682, 'spa', 'Abrasador, ardiente', 'Adjetivo que significa abrasador o ardiente, usado en Proverbios 16:27 para caracterizar el habla destructiva. El texto compara las palabras de una persona indigna con un «fuego abrasador», enfatizando cómo el discurso dañino quema y hiere como llamas que abrasan la carne.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130686, 'spa', 'Angustia, aflicción', 'Angustia, aflicción: el estado o condición de angustia, aflicción o tribulación experimentada como una realidad apremiante singular — congoja personal, crisis nacional o adversidad existencial. Con 57 apariciones, este sentido se manifiesta en el reconocimiento de Jacob de la «angustia del alma» de José (Gn 42:21), la frase «en el día de mi angustia» (Gn 35:3; Sal 77:3; 86:7) y el clamor de los israelitas a Dios «en el tiempo de su tribulación».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130688, 'spa', 'Tribulaciones, aflicciones', 'Tribulaciones, aflicciones: casos concretos y reiterados de aflicción y adversidad — el plural צָרוֹת referido a múltiples angustias experimentadas a lo largo del tiempo. Con 13 apariciones, este sentido surge en la advertencia de Moisés de que «muchas tribulaciones y aflicciones vendrán sobre ellos» (Dt 31:17, 21), y en la declaración del salmista: «muchas son las aflicciones del justo, pero de todas ellas lo libra el SEÑOR» (Sal 34:17-18).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130716, 'spa', 'Esposa rival', 'Designa a una esposa rival o coesposa en un matrimonio polígamo. Se usa en 1 Samuel 1:6 para describir la relación de Penina con Ana. El término subraya la naturaleza competitiva y hostil de su vínculo: Penina usaba su fertilidad para provocar y angustiar a la estéril Ana, ilustrando las dolorosas rivalidades propias de los hogares polígamos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130717, 'spa', 'Nombre propio hebreo que designa a la madre de Joab, Abisai y Asael, y hermana d', 'Nombre propio hebreo que designa a la madre de Joab, Abisai y Asael, y hermana de David (1 Cr 2:16). Casi todas las 26 ocurrencias usan la construcción ''hijo(s) de Sarvia'' como un patronímico virtual — la identificación materna resulta inusual y posiblemente insinúa un padre ausente o desconocido. La frase tiñe la narrativa davídica con un motivo recurrente de lealtad feroz mezclada con insubordinación. El exclamación exasperada de David ''¿Qué tengo yo con vosotros, hijos de Sarvia?'' (2 Sam 16:10; 19:22) se ha vuelto proverbial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130719, 'spa', 'Nombre propio femenino', 'Nombre de la madre de Jeroboam I, mencionada en 1 Reyes 11:26. El texto especifica que era viuda, señalando los orígenes no reales de su hijo antes de su rebelión contra Salomón y la fundación del reino del norte de Israel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130720, 'spa', 'Atado, paquete', 'Objetos amarrados o envueltos juntos en una sola unidad. Los hermanos hallan atados de dinero en sus costales (Gn 42:35), y Abigail promete a David que su vida estará «atada en el haz de los que viven» con el SEÑOR (1 S 25:29), metáfora entrañable aún recitada en oraciones funerarias judías.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130721, 'spa', 'Bolsa, monedero', 'Una bolsa, bolsillo o monedero: un recipiente diseñado para guardar objetos de valor, especialmente dinero. Job 14:17 describe la transgresión sellada en una bolsa, Proverbios 7:20 habla de un hombre que lleva una bolsa de dinero en su viaje, y Hageo 1:6 advierte memorablemente sobre ganar salarios solo para echarlos en una bolsa llena de agujeros.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130728, 'spa', 'Nombre propio masculino', 'Nombre propio del bisabuelo de Saúl en el linaje benjaminita. 1 Samuel 9:1 incluye a Zeror en la genealogía que establece la ascendencia tribal de Saúl, trazando su línea familiar a lo largo de varias generaciones de antepasados de la tribu de Benjamín.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130730, 'spa', 'Músico levita', 'Nombre de un músico levita, hijo de Jedutún, mencionado en 1 Crónicas 25:3 entre los designados para el ministerio musical profético en el templo. También llamado Izri en el versículo 11, encabezaba la tercera división de músicos en el culto organizado por David.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130731, 'spa', 'Bálsamo, resina curativa', 'Una resina aromática o bálsamo, apreciada por sus propiedades medicinales y curativas, producida en Galaad o asociada con esa región. Español ''bálsamo'', francés ''baume'' e inglés ''balm'' señalan una sustancia fragante de uso medicinal. Aparece como producto de comercio en las narrativas patriarcales (Gn 37:25, transportado por mercaderes ismaelitas; Gn 43:11, enviado como regalo a Egipto) y entre las exportaciones de Judá a Tiro (Ez 27:17).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130734, 'spa', 'Tirio, de Tiro', 'Adjetivo gentilicio que significa ''de Tiro'' o ''tirio,'' empleado tanto como adjetivo para describir individuos (1 R 7:14, el artesano Hiram) como sustantivo para los habitantes de Tiro en conjunto (1 Cr 22:4; Esd 3:7; Neh 13:16). Los tirios aparecen consistentemente como proveedores de materiales y mercancías, reflejando el papel de Tiro como potencia comercial mediterránea.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130735, 'spa', 'Fortaleza, refugio', 'Jueces 9:46 y 9:49 hacen referencia a la «fortaleza de la casa/templo de El-berit» (צְרִיחַ בֵּית אֵל בְּרִית) donde los líderes de Siquem se refugiaron antes de que Abimelec la incendiara. Primer Samuel 13:6 enumera «cuevas, espesuras, rocas, tumbas y cámaras subterráneas» (צְרִחִים) como escondites ante los filisteos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130736, 'spa', 'Necesidad o requerimiento', 'Término arameo que denota necesidad o requerimiento, empleado en 2 Crónicas 2:16 donde el rey Hiram promete a Salomón proveer madera «conforme a toda tu necesidad», subrayando que suministrará cuanta cantidad exija la construcción del templo, no una cantidad fija sino lo suficiente para satisfacer el requerimiento completo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130737, 'spa', 'Persona leprosa, leproso', 'Persona leprosa, leproso: una persona afligida con una enfermedad cutánea grave — el uso sustantivo, ''un leproso''. Cubre la mayoría de las ocurrencias. En Levítico 14:2, ''la ley del leproso'' (תּוֹרַת הַמְּצֹרָע) establece el ritual de purificación. Naamán es descrito como ''leproso'' (מְצֹרָע, 2 Reyes 5:1) a pesar de ser un poderoso comandante sirio — la ironía social intensifica la narrativa. Los cuatro leprosos de 2 Reyes 7:3 actúan como agentes inesperados de salvación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130739, 'spa', 'Leproso, enfermo (de parte del cuerpo)', 'Leproso, enfermo (de parte del cuerpo): el uso adjetival, típicamente en forma femenina singular describiendo una parte del cuerpo afectada por enfermedad cutánea. El ejemplo paradigmático es Éxodo 4:6, donde la mano de Moisés se vuelve ''leprosa como la nieve'' (מְצֹרַעַת כַּשָּׁלֶג) como señal de poder divino. Números 12:10 emplea la misma forma cuando Miriam es herida con la enfermedad como castigo por desafiar a Moisés.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130748, 'spa', 'Arma divina de conquista', 'Las tres ocurrencias presentan al avispón como agente de Dios en la conquista. Éxodo y Deuteronomio prometen su futuro despliegue, mientras Josué mira hacia atrás a su efectividad pasada. La unanimidad interlingüística (''hornet'', ''avispón'', ''Hornisse'') apoya un insecto literal, aunque el debate interpretativo continúa si esto es metafórico para pánico, enfermedad o enjambres reales. El singular ''el avispón'' (colectivo) permite ambas lecturas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130749, 'spa', 'Zora (topónimo)', 'Zora (tsorah), ciudad en la Sefelá (colinas bajas) de Judá, identificada con la moderna Sar''a a unos veinticuatro kilómetros al oeste de Jerusalén. Incluida en la herencia de Judá (Jos 15:33) pero asignada a Dan (Jos 19:41), ocupa una posición fronteriza. Su importancia bíblica principal es como hogar de Sansón: su padre Manoa era de Zora (Jue 13:2), el Espíritu del SEÑOR lo impulsó allí (Jue 13:25), y fue sepultado entre Zora y Estaol (Jue 16:31).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130755, 'spa', 'Clanes de Zora', 'Las tres referencias enumeran estos clanes dentro de las extensas genealogías de Judá en Crónicas. Las formas entre corchetes en alemán y francés señalan las variaciones ortográficas (צרעי vs. צרעתי), probablemente representando el mismo gentilicio básico con variación morfológica. Estas familias habitaban o se originaban del área de Zora (más tarde famosa como la ciudad natal de Sansón). El español ''los tsoreatitas'' se traduce como colectivo plural.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130756, 'spa', 'Condición ritualmente contaminante que exige inspección sacerdotal y elaborados ', 'Condición ritualmente contaminante que exige inspección sacerdotal y elaborados ritos de purificación. En Levítico 13-14, el sacerdote examina las lesiones cutáneas según color, profundidad y extensión para declarar tameh o tahor (Lv 13:2-8). La curación de Naamán (2 Re 5:1-14) y el castigo de Guejazí (2 Re 5:27) ilustran su función narrativa. Se extiende a vestiduras (Lv 13:47) y paredes de casas (Lv 14:34), denotando probablemente moho u hongos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130763, 'spa', 'Participio Qal sustantivado', 'Participio Qal sustantivado: orfebre, platero, metalúrgico -- 11 ocurrencias que identifican artesanos profesionales. La madre de Micaías entrega plata a un tsoreph para fundir un ídolo (Jue 17:4); los orfebres reparan secciones de la muralla de Jerusalén junto a perfumistas y mercaderes (Neh 3:8, 32); y el fabricante de ídolos recubre su imagen con oro mientras el tsoreph suelda cadenas (Is 40:19; 41:7; 46:6).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130764, 'spa', 'Qal activo', 'Qal activo: refinar, fundir o purificar metales o personas mediante el fuego -- 10 ocurrencias que abarcan tanto la metalurgia literal como su extensión figurada a la purificación divina. Dios declara ''fundiré tu escoria'' (Is 1:25); ''te he refinado, aunque no como a plata'' (Is 48:10); y ''los estoy refinando y probando'' (Jer 9:7). El imperativo del Salmo 26:2 -- ''refíname, oh SEÑOR, y pruébame'' -- subraya la entrega voluntaria a la prueba divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130765, 'spa', 'Participio Piel e infinitivo absoluto Qal', 'Participio Piel e infinitivo absoluto Qal: el refinador como agente, el que purifica -- 3 ocurrencias concentradas en la visión profética de Malaquías 3:2-3, donde el mensajero del pacto ''es como fuego de refinador'' y ''se sentará como refinador y purificador de plata.'' Jeremías 6:29 emplea el infinitivo absoluto tsaroph para describir el intento fallido de refinar a Israel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130766, 'spa', 'Participio pasivo Qal', 'Participio pasivo Qal: refinado, puro, probado -- 5 ocurrencias que describen el estado resultante de una purificación completada. La palabra de Dios es tsaruf, ''refinada'' (2 Sam 22:31; Sal 18:30; Pr 30:5), y el salmista declara las promesas de Dios ''sumamente puras'' (Sal 119:140). El emblemático Salmo 12:6 compara el habla divina con ''plata refinada en horno, purificada siete veces.''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130771, 'spa', 'Qal con extensión metafórica', 'Qal con extensión metafórica: probar, examinar, poner a prueba el carácter de una persona -- 4 ocurrencias donde la imagen metalúrgica se transfiere plenamente a la prueba moral. Dios ''probó'' a José mediante la palabra que le llegó (Sal 105:19); ''Tú me has probado'' (Sal 17:3); ''Nos has refinado como se refina la plata'' (Sal 66:10). El relato de Gedeón usa el verbo para la ''prueba'' divina de los guerreros junto al agua (Jue 7:4).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130777, 'spa', 'Nifal o Hitpael reflexivo', 'Nifal o Hitpael reflexivo: ser refinado, purificarse a sí mismo -- una sola ocurrencia en Daniel 12:10, en la promesa apocalíptica de que ''muchos se purificarán, se emblanquecerán y serán refinados.'' Este uso escatológico extiende la metáfora metalúrgica a la purificación del tiempo final, anticipando la restauración definitiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130790, 'spa', 'Gremio de orfebres', 'Sustantivo colectivo para los orfebres como gremio profesional, presente en Nehemías 3:31 en la frase «hijo de los orfebres», que indica pertenencia gremial. Esta designación muestra cómo los artesanos de la Jerusalén postexílica se organizaban en asociaciones de oficios, cuyos miembros contribuyeron a la reconstrucción de la muralla.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130791, 'spa', 'Ciudad fenicia', 'Dos contextos definen a Sarepta: la estancia de Elías allí (1 Reyes 17:9-10) y la esperanza profética de expansión territorial (Abdías 20). La viuda de Sarepta se convierte en un modelo de fe y hospitalidad, sosteniendo al profeta durante el hambre y recibiendo a su hijo de vuelta de la muerte. El sufijo direccional en algunas formas (Sarepta-ah, hacia Sarepta) indica movimiento hacia la ciudad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130792, 'spa', 'Angustia o aflicción', 'Significa estar angustiado o experimentar aflicción profunda, usado en Lamentaciones 1:20 donde Jerusalén personificada clama por su tormento interior y sufrimiento. El verbo transmite la vivencia de verse oprimido en estrecheces, constreñido por una tribulación abrumadora sin escapatoria ni alivio posible.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130794, 'spa', 'El sentido estativo/intransitivo del Qal de estar estrecho, constreñido o en ang', 'El sentido estativo/intransitivo del Qal de estar estrecho, constreñido o en angustia — 5 ocurrencias que describen el estado vivencial de alguien presionado por las circunstancias. Saúl dice a Samuel ''estoy en gran angustia'' (1 Sam 28:15); David lamenta ''angustia tengo por ti, hermano mío Jonatán'' (2 Sam 1:26); el salmista clama ''ten misericordia de mí, porque estoy en angustia'' (Sal 31:9; 69:17).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130795, 'spa', 'El sentido causativo Hifil de causar activamente angustia, traer tribulación o s', 'El sentido causativo Hifil de causar activamente angustia, traer tribulación o sitiar — 7 ocurrencias donde un agente (Dios, enemigos o circunstancias) inflige constricción sobre otros. Deuteronomio 28:52 advierte que el enemigo ''te sitiará en todas tus puertas''; 2 Crónicas 33:12 registra que cuando Dios ''angustió'' a Manasés, este se humilló; Nehemías 9:27 relata el ciclo de liberación y recaída. El español ''sitiar'' y ''angustiar'' captan las dos facetas del Hifil.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130796, 'spa', 'El sentido activo/transitivo del Qal de atar físicamente, envolver o amarrar — 5', 'El sentido activo/transitivo del Qal de atar físicamente, envolver o amarrar — 5 ocurrencias centradas en actos concretos de encierro. Dios ''ata'' las aguas en densas nubes (Job 26:8; Prov 30:4); Isaías 8:16 ordena ''ata el testimonio''; Oseas 4:19 describe al viento envolviendo a alguien en sus alas. El español ''atar'' y el árabe ''rabata'' usan vocabulario de atadura física.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130802, 'spa', 'El participio pasivo del Qal de estar atado, encerrado o confinado — 4 ocurrenci', 'El participio pasivo del Qal de estar atado, encerrado o confinado — 4 ocurrencias que describen el estado resultante tras la atadura. Las artesas de Israel estaban ''atadas'' en sus vestidos durante el Éxodo (Éx 12:34); la vida de David está ''atada en el haz de los vivientes'' con Dios (1 Sam 25:29); las concubinas de David quedaron ''encerradas'' hasta su muerte (2 Sam 20:3); la iniquidad de Efraín está ''atada,'' almacenada para el juicio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130810, 'spa', 'Una única ocurrencia Pual (pasivo-intensivo) en Josué 9', 'Una única ocurrencia Pual (pasivo-intensivo) en Josué 9:4 que describe los odres de los gabaonitas como ''remendados'' — es decir, atados y reparados. El español ''remendados,'' el inglés ''patched'' y la evidencia multilingüe más amplia seleccionan vocabulario de reparación en vez de atadura o angustia general. El tallo pasivo-intensivo se especializa en el resultado acabado del remiendo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130815, 'spa', 'El participio Qal sustantivado funcionando como nombre', 'El participio Qal sustantivado funcionando como nombre: ''adversario, enemigo, oponente.'' Aparece con sufijos pronominales (mi adversario, tu adversario) y en cadenas constructas (adversario de). El español ''enemigo de'' y el alemán ''Widersacher'' lo traducen consistentemente como un oponente personal. Dominante en Ester (3:10; 8:1; 9:10, 24) identificando a Amán, y en Salmos y textos proféticos identificando adversarios nacionales o personales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130818, 'spa', 'La acción verbal de hostigar, angustiar u oprimir, atestiguada en formas finitas', 'La acción verbal de hostigar, angustiar u oprimir, atestiguada en formas finitas (perfecto, imperfecto, infinitivo absoluto). El español ''hostigar'' y el francés ''harceler'' captan la naturaleza activa y continua de la hostilidad. Pasajes clave incluyen la orden de hostigar a los madianitas (Núm 25:17), la advertencia de que los remanentes cananeos hostigarán a Israel (Núm 33:55), y el lamento del salmista de que los enemigos lo han oprimido desde su juventud (Sal 129:1-2).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130829, 'spa', 'Hacer esposa rival', 'Verbo denominativo que significa tomar como esposa rival o convertir en coesposa, empleado en Levítico 18:18 en la prohibición de casarse con la hermana de la esposa mientras esta viva. El verbo reconoce que tomar tal segunda esposa genera una situación de rivalidad, y esta configuración familiar particular queda prohibida.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130830, 'spa', 'Topónimo corrupto', 'Nombre de lugar probablemente corrupto que aparece en Jueces 7:22, señalando la dirección de la huida de los madianitas tras su derrota. La mayoría de los especialistas cree que debería leerse Zaretán o Zereda, localidades conocidas en el valle del Jordán. Independientemente de su forma original, identifica la dirección de la retirada desesperada del enemigo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130831, 'spa', 'Nombre personal', 'Nombre de un descendiente de Judá mencionado en 1 Crónicas 4:7 entre los registros genealógicos de su tribu. Fuera de su inclusión en esta genealogía, no se conserva ninguna otra información sobre Zéret, aunque su presencia en las crónicas preservó su vínculo con el linaje tribal de Judá.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130832, 'spa', 'Ciudad de Rubén', 'Nombre de una ciudad asignada a la tribu de Rubén, mencionada en Josué 13:19 entre sus ciudades territoriales. Su nombre podría significar «esplendor del alba». Se ha identificado con un emplazamiento en las tierras altas al este del mar Muerto, como parte de la heredad transjordana de Rubén.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130833, 'spa', 'Ubicación en el Jordán', 'Tres usos anclan a Saretán en la geografía del Valle del Jordán: el milagro del cruce de Josué, las operaciones de fundición de bronce de Salomón, y límites administrativos. El texto paralelo en Crónicas (''Zereda'') sugiere variación textual o posible fusión con otro sitio cercano. Las traducciones interlingüísticas son bastante consistentes (Zarethan, Saretán), aunque la identificación exacta del sitio elude a los arqueólogos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130834, 'spa', 'Vómito', 'Designa el vómito o lo expulsado del estómago. Se usa en Proverbios 26:11 en un símil vívido sobre la conducta necia: el proverbio compara al insensato que repite su necedad con un perro que vuelve a su vómito, siendo ambas acciones repugnantes e irracionales, un retorno absurdo a lo que debería abandonarse.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130835, 'spa', 'Vómito metafórico', 'Los tres usos son figurativos: profetas ebrios profanando espacios sagrados (Isaías 28:8), la confusión de Egipto comparada con un borracho (19:14), y la humillación de Moab en juicio (Jeremías 48:26). La metáfora del vómito transmite disgusto, pérdida de control y degradación. El español ''vómito'' y las formas francesas (algunas entre corchetes, sugiriendo notas morfológicas) reconocen uniformemente el referente desagradable. La imagen sirve para el juicio profético.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130836, 'spa', 'Ave impura del desierto', 'Ave impura de identificación incierta, tradicionalmente traducida como ''pelícano'' pero posiblemente una especie de búho o avetoro propia de hábitats desolados. Catalogada como ritualmente impura (Lv 11:18; Dt 14:17) y asociada con lugares arruinados y abandonados (Is 34:11; Sof 2:14). En el Salmo 102:6 el salmista se compara con esta criatura en el desierto como imagen de profunda soledad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130837, 'spa', 'Medida de áridos', 'Medida hebrea estandarizada para áridos, con un volumen aproximado de 2 litros, usada en el comercio y la vida cotidiana. Su única referencia bíblica (2 Reyes 6:25) aparece en un relato estremecedor de hambruna donde incluso fracciones mínimas de esta medida se convertían en bienes preciados, revelando cómo las unidades de medida sustentaban la economía antigua incluso en su colapso.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130838, 'spa', 'Maldecir', 'Proferir una maldición formal contra alguien, pronunciar una imprecación hablada. Se concentra en la narrativa de Balaam (Nm 22-24), donde Balac encarga a Balaam maldecir (קָבַב) a Israel, pero Dios convierte cada maldición en bendición (Nm 23:8, 11, 25, 27). También aparece en Job 3:8 para los expertos en maldecir días y en Proverbios 11:26; 24:24 para la maldición social contra los injustos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130845, 'spa', 'Estómago sacrificial', 'La porción estomacal de un animal sacrificial asignada al sacerdocio, probablemente el cuarto compartimento (abomaso) del ganado vacuno u ovino. Las traducciones en español, francés y alemán coinciden en traducirlo como «estómago», reflejando su función dentro del sistema sacrificial donde ciertos órganos se destinaban al consumo sacerdotal en lugar de quemarse sobre el altar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130846, 'spa', 'Vientre femenino', 'La zona del vientre o abdomen de una mujer, empleado en un relato de muerte violenta. La forma con sufijo (qobatah, «su vientre») aparece únicamente en el episodio de Finees, donde su lanza atraviesa los cuerpos de ambos transgresores. Las traducciones interlingüísticas prefieren «vientre/abdomen» (español vientre, francés ventre) sobre la terminología técnica de estómago, señalando una referencia anatómica general.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130847, 'spa', 'Tienda abovedada', 'Una estructura de tienda especializada, grande y arquitectónicamente distintiva con construcción abovedada o en forma de cúpula. El contexto de Números 25:8 sugiere que podría tratarse de la morada de un noble o posiblemente de una tienda utilizada para actividad sexual cúltica. Los estudiosos debaten si era el aposento principesco de Zimri o un recinto que funcionaba como lupanar, anclándose ambas interpretaciones en su notable tamaño y forma.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130848, 'spa', 'Colección de ídolos', 'Una masa o colección de objetos, referida específicamente a ídolos reunidos en la denuncia profética de Isaías. El sufijo femenino de segunda persona («tus colecciones») se dirige a Jerusalén personificada, desafiándola a buscar liberación en los mismos ídolos que ha acumulado. El campo semántico involucra reunir y agrupar, aunque las variantes textuales sugieren cierta incertidumbre escribal sobre la lectura original.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130849, 'spa', 'Tumba, sepulcro, lugar de entierro', 'Tumba, sepulcro, lugar de entierro. El sitio físico donde una persona fallecida es sepultada —una tumba, fosa o sepulcro—. Con frecuencia lleva sufijos posesivos que indican de quién es el lugar de reposo. La qevurat de Raquel (Gn 35:20) se convirtió en un memorial con nombre propio; el lugar de sepultura de Moisés (Dt 34:6) permaneció célebremente desconocido. El español sepulcro y el francés tombeau traducen consistentemente este sentido concreto, distinguiéndolo del acto abstracto de entierro.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130852, 'spa', 'Entierro, acto de sepultar', 'Entierro, acto de sepultar. El acto o proceso de enterrar a alguien —el rito funerario o la inhumación en sí, más que el sitio físico—. La devastadora expresión de Jeremías ''sepultura de asno'' (Jer 22:19) emplea este sentido: Joacim no recibirá una tumba deshonrosa, sino que carecerá de toda sepultura digna. Isaías 14:20 se refiere igualmente a ser arrojado, privado del acto de entierro. El español sepultura y el alemán Begräbnis captan este significado orientado al evento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130860, 'spa', 'Recibir, tomar', 'Recibir, tomar. Recibir o tomar algo dado, ya sean objetos físicos como la sangre sacrificial (2 Cr 29:22), los utensilios del templo (Esd 8:30), o de manera más abstracta lo bueno y lo malo de parte de Dios (Job 2:10). Las glosas multilingües convergen en ''recibir/recevoir'', confirmando un significado directo de transferencia de posesión.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130862, 'spa', 'Corresponder, estar en posición opuesta', 'Corresponder, estar en posición opuesta. Hifil: corresponderse mutuamente, estar colocados uno frente al otro. Se usa exclusivamente respecto a los lazos de las cortinas del tabernáculo (Éx 26:5; 36:12), donde cada lazo queda frente a su par. Este sentido preserva el significado espacial original de la raíz aramea —''estar delante de, enfrentado''— y todas las traducciones principales lo expresan con un término de correspondencia espacial (''correspondientes'' en español).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130863, 'spa', 'Aceptar, comprometerse', 'Aceptar, comprometerse. Aceptar voluntariamente, estar de acuerdo con, o asumir una obligación. Se distingue del sentido 1 por la volición: los judíos aceptaron y se comprometieron a observar Purim (Est 9:23, 27), David eligió su castigo (1 Cr 21:11), y Proverbios 19:20 exhorta a aceptar la instrucción. El español ''aceptaron'' y el francés ''recevoir'' aparecen aquí, pero el contexto de compromiso establece la diferencia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130869, 'spa', 'Recibir posesión', 'Tres contextos en Daniel muestran objetos variados de recepción: recompensas condicionales (2:6, si interpretan), transferencia histórica de poder (5:31, Darío recibió), y promesa escatológica (7:18, los santos recibirán). El español distingue bien los tiempos (''recibiréis'', ''recibió'', ''recibirán''), siguiendo los cambios temporales desde promesa a pasado a futuro. El acuerdo interlingüístico sobre ''recibir'' confirma la semántica central del verbo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130870, 'spa', 'El sentido causal — ''a causa de, por motivo de, por tanto'' — representa la gran ', 'El sentido causal — ''a causa de, por motivo de, por tanto'' — representa la gran mayoría de las apariciones (27x). Introduce razones en correspondencia oficial (Esd 4:14, 16) y explicaciones narrativas en los relatos cortesanos de Daniel (Esd 6:13; 7:14, 17). El alemán weil y el francés parce que reflejan consistentemente esta lógica causal. La construcción לָקֳבֵל דְּנָה (''por causa de esto'') funciona como un conector discursivo estándar en el arameo imperial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130875, 'spa', 'El sentido espacial — ''delante de, enfrente de, frente a'' — aparece solo dos vec', 'El sentido espacial — ''delante de, enfrente de, frente a'' — aparece solo dos veces, ambas en Daniel. En Daniel 2:31, la gran estatua estaba לָקֳבְלָךְ, ''delante de ti,'' en el sueño de Nabucodonosor. En Daniel 5:1, Belsasar bebe vino ''delante de'' sus mil nobles. El español frente a ti y el inglés ''before you'' captan este significado locativo. El cognado siríaco luqbal conserva la misma fuerza espacial, confirmando la distinción original entre los dos sentidos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130877, 'spa', 'Ariete de asedio', 'Un arma de asedio o ariete utilizado para derribar fortificaciones, mencionado en la profecía de Ezequiel contra Tiro. La frase «el golpe de su máquina de ataque» evoca el impacto repetido de la maquinaria de asedio babilónica contra las murallas de la ciudad. El español lo traduce como ariete, reconociendo el equipo militar técnico, mientras que algunas versiones modernas mantienen el hebreo sin transliterar debido a su rareza.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130879, 'spa', 'Robar, despojar', 'Robar, despojar o defraudar a alguien, en particular reteniendo lo que legítimamente pertenece a otro. El verbo aparece de forma más concentrada en Malaquías 3:8-9, donde cuatro de sus seis apariciones conforman una confrontación dramática: ''¿Robará el hombre a Dios? Pues vosotros me robáis. Y decís: ¿En qué te robamos? En los diezmos y las ofrendas.'' En español ''robáis'' y en alemán ''beraubt'' captan la contundencia de la acusación divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130885, 'spa', 'Qal: recoger, juntar', 'Qal activo simple: recoger, juntar — 36 ocurrencias de reunión transitiva directa de personas, animales o cosas por un agente. En Gn 41:35, José propone ''recoger todo el alimento'' de los años buenos; en Gn 41:48 ''recogió todo el alimento''. Dt 13:16 ordena juntar todo el botín de una ciudad condenada. En 1 S 7:5, Samuel dice ''reunid a todo Israel en Mizpa''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130886, 'spa', 'Piel: reagrupar, reunir', 'Piel intensivo: reunir deliberadamente, reagrupar — el sentido más frecuente con 50 ocurrencias, dominado por las promesas proféticas de restauración nacional. En Dt 30:3-4, Dios promete ''os reunirá (קִבֶּצְךָ) de nuevo de entre todos los pueblos''. Ezequiel despliega este verbo repetidamente para las promesas de retorno del exilio, convirtiéndolo en la expresión técnica de la esperanza mesiánica de Israel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130887, 'spa', 'Nifal/Hitpael: congregarse', 'Nifal e Hitpael: congregarse, ser reunidos, juntarse — la voz media/pasiva/reflexiva con 39 ocurrencias donde el énfasis recae sobre el grupo reunido más que sobre el agente. En Gn 49:2, Jacob convoca a sus hijos: ''¡Juntaos (הִקָּבְצוּ) y escuchad!''. En Jos 9:2 y 10:6, reyes enemigos ''se congregaron'' contra Israel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130949, 'spa', 'Pual/QalPas: estado reunido', 'Pual o participio pasivo del Qal: en estado de reunión, ya congregados — 2 ocurrencias que describen una condición resultante en vez del acto de reunir. En Neh 5:16, los siervos de Nehemías ''estaban reunidos allí'' (קְבוּצִים) para la obra del muro; en Ez 38:8, el Israel restaurado es descrito como un pueblo ''reunido (מְקֻבֶּצֶת) de muchas naciones''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130954, 'spa', 'Ciudad natal de Benaía', 'Dos contextos definen a Cabseel: la lista territorial (Josué 15:21) y la identificación de Benaía (2 Samuel/1 Crónicas). La forma preposicional ''de Cabseel'' en las referencias a Benaía la marca como su lugar de origen. La mención de Nehemías (usando una forma variante con prefijo beth) indica reasentamiento post-exílico. Las traducciones muestran variaciones ortográficas (Cabseel, Cabtseel, Qavtseel) pero mantienen consistencia en la identificación geográfica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130957, 'spa', 'ser sepultado (Nifal/Pual)', 'Nifal y Pual pasivos: ser sepultado, ser enterrado. Esta forma tiene un peso teológico inmenso en la historia deuteronomista, donde la fórmula ''y fue sepultado en...'' (וַיִּקָּבֵר בְּ) señala el cierre de la vida de un rey o juez. Recibir sepultura digna es marca del favor divino y del honor social; la negación de sepultura constituye uno de los juicios más severos de la Escritura (Jer 22:19).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130958, 'spa', 'sepultar (Qal activo)', 'El sentido nuclear en Qal activo: sepultar a un difunto en tumba o sepulcro. Abarca la gran mayoría de las ocurrencias con formas finitas, infinitivos e infinitivo absoluto. Abraham sepulta a Sara en la cueva de Macpela (Gn 23:19), José cumple el deseo de Jacob de ser sepultado en Canaán (Gn 50:13), y Dt 21:23 exige que incluso un ejecutado sea enterrado antes del anochecer.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130972, 'spa', 'el que sepulta (participio Qal)', 'Participio activo del Qal usado como nombre de agente: el que sepulta, un enterrador circunstancial. Se distingue del sentido 3 por la conjugación (Qal en lugar de Piel) y por carecer de connotación organizativa o profesional. En 2 R 9:10 se declara que Jezabel no tendrá ''quien la sepulte'' (אֵין קֹבֵר), y el Sal 79:3 lamenta que los muertos de Jerusalén no tienen ''quien los entierre''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130975, 'spa', 'sepulturero (participio Piel)', 'Forma participial del Piel usada como sustantivo: un sepulturero designado, encargado de enterramientos a gran escala. El pasaje clave es Ez 39:14-15, donde se nombran הַקֹּבְרִים (''los sepultureros'') profesionales para purificar la tierra tras la derrota de Gog — una operación de siete meses que requiere equipos organizados que señalizan los huesos hallados.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (130979, 'spa', 'sepultar a fondo (Piel intensivo)', 'Piel finito/intensivo: llevar a cabo la sepultura de manera exhaustiva o a gran escala, enfatizando completitud o esfuerzo más allá del entierro ordinario. En 1 R 11:15, Joab permanece en Edom seis meses ''hasta haber sepultado a todos los varones'' — un enterramiento masivo en tiempo de guerra. Os 9:6 advierte que Menfis de Egipto ''los sepultará'', oráculo sombrío de muerte en el exilio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131013, 'spa', 'Sepulcro, tumba, lugar de sepultura', 'Sepulcro, tumba, lugar de sepultura: lugar donde se deposita un cuerpo muerto, desde una simple fosa hasta un sepulcro labrado en roca. La compra que Abraham hizo de la cueva de Macpela como אֲחֻזַּת־קֶבֶר (Gn 23:4, 9, 20) establece tempranamente el sentido concreto del término, mientras que la metáfora del vientre como sepulcro en Jeremías (Jer 20:17) y las fosas comunes de las naciones en Ezequiel (Ez 32:22-26) muestran su alcance figurado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131046, 'spa', 'Campamento del desierto', 'Nombre propio que designa un campamento entre el Sinaí y Hazerot, cuyo significado literal es ''sepulcros de la codicia.'' Recibió ese nombre porque los israelitas que codiciaron carne fueron heridos y sepultados allí (Nm 11:34). Mencionado en las listas de itinerario (Nm 33:16-17) y en el recuento de las rebeliones (Dt 9:22).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131047, 'spa', 'Inclinarse, postrarse', 'Inclinarse, postrarse. Inclinar la cabeza o el torso hacia abajo como gesto de adoración, reverencia u homenaje deferente. Prácticamente cada aparición va acompañada de wayyishtaḥû (''y se postró''), lo que sugiere que qādad denota el movimiento inicial de inclinación que precede a la postración completa. Se dirige a Dios en adoración (Gn 24:26, 48; Éx 4:31; 12:27; 34:8; Neh 8:6; 2 Cr 20:18; 29:30) y a reyes en homenaje cortesano.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131055, 'spa', 'santo (atributo divino)', 'Predicación adjetival de santidad: קָדוֹשׁ usado predicativa o atributivamente para describir a Dios, personas, lugares, objetos o tiempos como sagrados o apartados. Es el sentido más amplio con 50 ocurrencias, que abarca ''nación santa'' (Éx 19:6), ''lugar santo'' (Lv 6:16, 26-27), ''tierra santa'' (Éx 3:5) y ''seréis santos'' (Lv 11:44-45; 19:2; 20:7).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131056, 'spa', 'el Santo (título divino)', 'Título divino sustantivado: ''el Santo'' (הַקָּדוֹשׁ o קְדוֹשׁ) usado como nombre de Dios, de manera más característica en la frase constructa קְדוֹשׁ יִשְׂרָאֵל, ''el Santo de Israel''. Con 46 ocurrencias, es el epíteto divino distintivo de Isaías (Is 1:4; 5:19, 24; 10:17, 20; 12:6; 30:11-12, 15; 41:14, 16, 20; 43:3, 14-15; 54:5; 55:5; 60:9, 14), aunque aparece también en Salmos y otros profetas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131057, 'spa', 'santos, seres celestiales', 'Sustantivo plural: קְדוֹשִׁים que significa ''santos'' o ''seres celestiales'' — ya sean ángeles del consejo divino o seres humanos consagrados a Dios. Veinte ocurrencias abarcan ambos referentes: Dt 33:3 habla de los קְדֹשָׁיו (''sus santos'') viniendo desde el Sinaí con huestes angélicas; Sal 34:10 exhorta: ''Temed al SEÑOR, vosotros sus santos''; y Dn 7:18, 22 identifica a los santos como herederos del reino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131062, 'spa', 'ofrendas sagradas', 'Ofrendas santas o donaciones sagradas: קָדוֹשׁ en estado constructo con genitivo, referido a objetos consagrados o porciones apartadas para uso sacerdotal. Dos ocurrencias en Nm 18:8 y 18:32, donde designa las ofrendas sagradas que los levitas reciben y deben manejar con reverencia, marcando un desplazamiento semántico de persona santa a cosa santa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131080, 'spa', 'recinto sagrado', 'Recinto santo o espacio sagrado: קָדוֹשׁ en estado constructo para designar un lugar santificado o los atrios santos de la morada de Dios. Una ocurrencia en Sal 65:5, donde el salmista habla de saciarse con ''la santidad de tu casa'' — el santuario como lugar de la presencia divina y la bendición, con un matiz espacial-sacral.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131086, 'spa', 'encender, arder', 'Encenderse o prender fuego, usado predominantemente para la ira divina que estalla en llamas. En Dt 32:22 ''un fuego se ha encendido en mi ira'' establece el modismo teologico dominante, repetido en Jer 15:14 y 17:4. Isaias 64:2 lo extiende a la teofania: la venida de Dios es como fuego que enciende la maleza seca. Isaias 50:11 advierte a los autosuficientes ''encendedores de fuego''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131088, 'spa', 'Este, hacia el oriente (dirección)', 'Este, hacia el oriente (dirección): el punto cardinal este, usado para orientación geográfica, delimitación territorial y movimiento direccional. Ezequiel lo emplea profusamente para la puerta oriental del templo y la distribución de tierras tribales (Ez 11:1; 48:1-28). El sufijo locativo קָדִימָה (''hacia el este'') aparece con frecuencia en descripciones de fronteras.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131091, 'spa', 'Viento del este (viento abrasador del desierto)', 'Viento del este (viento abrasador del desierto): el viento ardiente y seco que sopla desde el este, el siroco bíblico — agente de destrucción frecuentemente usado por Dios como instrumento de juicio. Marchita el grano del faraón (Gn 41:6, 23, 27), abre el mar Rojo (Éx 14:21) y se convierte en metáfora de vacuidad en Job y Oseas (Job 15:2; Os 12:2; 13:15).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131103, 'spa', 'Santo, sagrado (arameo)', 'Santo, sagrado (arameo). Apartado, sagrado, consagrado —aplicado en el arameo de Daniel a tres referentes: el espíritu de los dioses que mora en Daniel (Dn 4:5–6; 5:11), los vigilantes angélicos enviados desde el consejo celestial (Dn 4:10, 14, 20), y la comunidad escatológica (''santos del Altísimo'') que hereda el dominio (Dn 7:18, 22, 25, 27). La consistencia del alemán heilig y el español santos en todos los usos confirma un único campo semántico unificado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131109, 'spa', 'Piel con intención hostil', 'Piel con intención hostil: caer sobre alguien o confrontarlo agresivamente, referido a enemigos, lazos o calamidades que se abalanzan sobre una persona. Las cuerdas de la muerte y los torrentes de destrucción ''confrontaron'' a David (2 Sam 22:6, 19; Sal 18:5, 19), y el salmista pide a Dios que ''confronte'' al impío y lo derribe (Sal 17:13). El español me confrontaron y el inglés ''confront'' convergen claramente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131110, 'spa', 'Hifil causativo', 'Hifil causativo: dar a alguien primero o por anticipado, anticipar con un obsequio previo. Una sola aparición en Job 41:11 (en inglés 41:3): ''¿Quién me ha confrontado para que yo le restituya?'' — es decir, ''¿quién me ha dado de antemano?'' La raíz Hifil marca explícitamente el causativo, y la evidencia multilingüe refleja el cambio: el español anticipar y el francés aller au-devant retienen la idea de ''adelantarse.''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131111, 'spa', 'Piel con intención social o de bienvenida', 'Piel con intención social o de bienvenida: salir al encuentro de alguien, ya sea en amistad, hospitalidad o encuentro formal. Moab y Amón no ''salieron al encuentro'' de Israel con pan y agua (Dt 23:4; Neh 13:2); Job pregunta por qué las rodillas lo ''recibieron'' al nacer (Job 3:12). El español salir al encuentro y el alemán meet-ihn captan la dinámica interpersonal cálida de este sentido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131112, 'spa', 'Piel con matiz benefactivo', 'Piel con matiz benefactivo: salir al encuentro de alguien llevando provisión, favor o bendición. Dios ''sale al encuentro'' del rey con bendiciones de bondad (Sal 21:3), y se anticipa que la misericordia de Dios ''saldrá al encuentro'' del salmista (Sal 59:10). Este sentido incluye también el avanzar contra una ciudad en asedio (2 Re 19:32; Is 37:33), donde el beneficio es irónico — el ''encuentro'' es una llegada con fuerza militar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131114, 'spa', 'Piel en contexto litúrgico', 'Piel en contexto litúrgico: presentarse ante la presencia de Dios en adoración o súplica. La pregunta retórica de Miqueas ''¿Con qué me presentaré ante el SEÑOR?'' (Miq 6:6, usada dos veces) y la invitación a ''venir ante su presencia con acción de gracias'' (Sal 95:2) representan este uso distintivamente teofánico. El español presentarse y el alemán kommen vor seleccionan vocabulario de aproximación formal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131122, 'spa', 'Piel con prioridad temporal o espacial', 'Piel con prioridad temporal o espacial: ir delante, preceder, anticiparse o madrugar. El salmista ''se adelanta'' al alba (Sal 119:147) y ''anticipa'' las vigilias de la noche (Sal 119:148). Jonás huyó ''de antemano'' a Tarsis (Jon 4:2), y los cantores ''iban delante'' de la procesión (Sal 68:25). El español adelantarse capta con precisión este sentido de prioridad temporal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131134, 'spa', 'Oriente, dirección oriental', 'Oriente, dirección oriental: el este como dirección geográfica o región oriental. Este sentido aparece desde Génesis 2:8 (''un huerto en el oriente'') hasta la literatura profética (Is 9:12, ''los sirios desde el oriente''). Los ''hijos del oriente'' (בְנֵי־קֶדֶם) en Jueces 6:3; 7:12 y Job 1:3 designan tribus que habitaban al este y noreste de Canaán.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131136, 'spa', 'Tiempo antiguo, desde antaño', 'Tiempo antiguo, desde antaño: antigüedad, tiempo remoto o «desde antiguo». Este sentido temporal aparece en Deuteronomio 33:27 (''el Dios eterno,'' lit. ''Dios de קֶדֶם''), 2 Reyes 19:25 (''¿no has oído que desde tiempos antiguos yo lo dispuse?'') y Salmo 74:12 (''Dios es mi rey desde la antigüedad''). La metáfora subyacente es profundamente hebrea: lo que está «delante» es lo que ya se ha visto, es decir, el pasado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131147, 'spa', 'Delante de, antes de', 'Delante de, antes de: en sentido espacial o temporal. El Salmo 139:5 sitúa a Dios «detrás y delante (קֶדֶם)» del salmista, un cerco espacial. Proverbios 8:22-23 declara que la Sabiduría fue establecida «desde el principio» (מִקֶּדֶם), antes de que existiera la tierra — un «delante de» temporal respecto a toda la creación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131162, 'spa', 'El adverbio direccional ''hacia el oriente'' o ''en dirección al este,'' formado con', 'El adverbio direccional ''hacia el oriente'' o ''en dirección al este,'' formado con el sufijo he-locale sobre קֶדֶם. Se usa predominantemente en las descripciones sacerdotales de fronteras y campamentos (Nm 2:3; 3:38; 34:3, 10-11; Jos 15:5; 18:20), en rúbricas sacrificiales que requieren orientación hacia el este (Lv 1:16; 16:14), y en indicaciones narrativas de dirección (Gn 25:6; 1 Re 17:3). En la visión del templo de Ezequiel, la puerta orientada al este porta un significado teológico especial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131167, 'spa', 'Preposición espacial y relacional que significa ''delante de, en presencia de,'' u', 'Preposición espacial y relacional que significa ''delante de, en presencia de,'' usada 45 veces en contextos formales arameos de corte y culto. Rige sufijos pronominales en todas las personas (qodamai, qodamakh, qodamohi, etc.). La evidencia multilingüe es notablemente uniforme: francés devant, español ante/delante de, alemán vor, todos espaciales. Pasajes clave incluyen Daniel 2:9 (''decir delante de mí'') y Esdras 4:18.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131175, 'spa', 'Preposición temporal que significa ''antes de, previamente,'' atestiguada una sola', 'Preposición temporal que significa ''antes de, previamente,'' atestiguada una sola vez en Daniel 7:7 al describir a la cuarta bestia devorando lo que había antes de ella. Las traducciones multilingües se dividen claramente aquí: el árabe pasa de amama (espacial) a qablaha (temporal), el español de delante de a antes de ella, y el hindi usa usse pahle (''antes de eso'' en tiempo). Esta convergencia entre familias lingüísticas no emparentadas confirma una distinción semántica genuina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131179, 'spa', 'Al este de', 'Génesis 2:14 localiza el Tigris «al este de Asiria» (קִדְמַת אַשּׁוּר), aunque geográficamente queda al oeste; la designación refleja el punto de vista occidental del narrador. Génesis 4:16 sitúa la morada de Caín «al este de Edén». 1 Samuel 13:5 ubica a los filisteos «al este de Bet-avén». Ezequiel 39:11 describe un valle de sepultura «al este del mar».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131180, 'spa', 'Estado anterior', 'Estado o condición previa, especialmente en contextos proféticos de restauración. Ezequiel 16:55 emplea la forma sufijada tres veces prometiendo el retorno al estado anterior de Sodoma, Samaria y Jerusalén. Ezequiel 36:11 extiende este sentido a los ''tiempos anteriores'' de Israel. El español ''antigüedad'' abarca tanto la noción de antiguo como la de condición previa restaurable.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131182, 'spa', 'Origen o anterioridad', 'Origen, principio o anterioridad temporal, referido al punto más remoto de existencia o a un tiempo previo a un evento dado. Isaías 23:7 habla del ''origen'' de Tiro que se remonta a la antigüedad. El Salmo 129:6 usa la forma constructa como conjunción temporal de influencia aramea con el sentido de ''antes de que (sea) arrancado''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131188, 'spa', 'Oriental', 'Perteneciente a la dirección geográfica del este. Se usa para la puerta oriental del templo en la visión de Ezequiel (Ez 10:19; 11:1), el mar oriental —es decir, el Mar Muerto— como límite fronterizo (Ez 47:18; Zac 14:8), y la referencia al mar oriental en Joel 2:20. La raíz קדם vincula ''este'' con ''frente'', reflejando la orientación israelita.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131189, 'spa', 'Anterior, antiguo', 'Anterior o antiguo, referido a lo que pertenece a tiempos pasados o generaciones previas. En Isaías 43:18, Dios ordena a Israel no detenerse en las קַדְמֹנִיּוֹת, ''cosas anteriores''. Malaquías 3:4 recuerda שָׁנִים קַדְמֹנִיּוֹת, ''años antiguos''. El plural sustantivado en Job 18:20 designa a ''los de antes'', gente de una era anterior que se estremece ante el malvado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131194, 'spa', 'Ciudad levítica', 'Deuteronomio 2:26 menciona el «Desierto de Quedemot» (מִדְבַּר קְדֵמוֹת), desde donde Moisés envió emisarios a Sehón. Josué 13:18 la lista entre las ciudades de Rubén. Josué 21:37 y 1 Crónicas 6:79 la designan como ciudad levítica. La Septuaginta transcribe el nombre como Κεδαμωθ y Καδημωθ con ligeras variaciones.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131195, 'spa', 'Precedencia temporal', 'Las visiones apocalípticas de Daniel usan este adjetivo para ordenar elementos: la primera bestia (7:4) establece secuencia, mientras que ''los cuernos anteriores'' (7:8, 24) son aquellos arrancados por el cuerno pequeño. La evidencia multilingüe muestra notación morfológica (corchetes para [קדמיא], [קדמיתא]), reflejando las diversas formas arameas (masculino/femenino, singular/plural). El significado básico es precedencia temporal: lo que vino primero.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131196, 'spa', 'Cadmiel (nombre propio)', 'Nombre propio levítico teofórico que significa «El es el antiguo», de qedem (antigüedad) más El. Identifica a un prominente líder levita postexílico. Aparece entre los que regresaron del exilio (Esd 2:40 = Neh 7:43), supervisó los cimientos del Templo (Esd 3:9), dirigió la oración comunal (Neh 9:4-5) y firmó el pacto (Neh 10:10).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131200, 'spa', 'Coronilla', 'La coronilla o vértice anatómico del cráneo, el punto más alto de la cabeza. Aparece frecuentemente en paralelismo poético con «cabeza» (רֹאשׁ), especialmente en bendiciones donde el favor reposa sobre la coronilla (Gn 49:26; Dt 33:16) y en maldiciones donde la aflicción cubre desde el pie hasta la coronilla (Dt 28:35). El español «coronilla» refleja cabalmente el sentido hebreo de la cima de la cabeza como lugar de honra o exposición.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131211, 'spa', 'Estar de luto, enlutarse', 'Estar de luto, enlutarse: andar de luto, caminar en tinieblas o asumir la apariencia desaliñada de un doliente. El rostro ensombrecido y las vestiduras descuidadas del duelo subyacen a esta extensión metafórica (cf. Sal 35:14; 38:7; 42:10; 43:2). Jeremías 8:21 combina conmovedoramente la oscuridad emocional y la física.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131212, 'spa', 'Oscurecerse, ennegrecerse', 'Oscurecerse, ennegrecerse: volverse oscuro o negro, dicho del mundo físico — el cielo nublándose (1 R 18:45; Jer 4:28), cuerpos celestes perdiendo su luz (Jl 2:10; 4:15), la piel oscureciéndose (Job 30:28) o aguas turbias (Job 6:16). Las formas Qal e Hitpael describen un proceso intransitivo de estos fenómenos naturales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131215, 'spa', 'Causar oscuridad, oscurecer', 'Causar oscuridad, oscurecer: causar tinieblas, oscurecer algo — la forma causativa Hifil. Usado exclusivamente del juicio de Dios en Ezequiel (31:15; 32:7-8), donde el Señor activamente oscurece los cielos, el sol, la luna y las estrellas sobre Egipto. El cambio de intransitivo a causativo subraya la soberanía divina sobre la luz misma.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131224, 'spa', 'Quedar (nombre propio)', 'Segundo hijo de Ismael (Gn 25:13; 1 Cr 1:29) y la tribu árabe nómada que desciende de él. Conocidos por sus tiendas negras de pelo de cabra (Cnt 1:5; Sal 120:5). Isaías anuncia la decadencia de Quedar (Is 21:16-17), pero también prevé que sus rebaños sirvan a Jerusalén (Is 60:7). Jeremías registra la campaña de Nabucodonosor contra ellos (Jer 49:28); Ezequiel los menciona entre los comerciantes de Tiro (Ez 27:21).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131229, 'spa', 'Cedrón (nombre propio)', 'Nombre propio del wadi (valle de arroyo estacional) al este de Jerusalén, entre el Monte del Templo y el Monte de los Olivos. Funciona como frontera geográfica y simbólica: David lo cruza huyendo de Absalón (2 S 15:23), Salomón lo establece como línea de muerte para Simei (1 R 2:37), y los reformadores queman allí objetos idolátricos (1 R 15:13; 2 R 23:4, 6). En español se traduce «Cedrón» o «Kidrón».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131232, 'spa', 'santificar, consagrar (Piel)', 'El Piel factitivo es el eje de la consagración bíblica: un agente hace activamente santo a alguien o algo. Dios santifica el séptimo día (Gn 2:3), Moisés consagra al pueblo (Éx 19:14), e Israel recibe el mandato de santificar el sábado (Éx 20:8). El árabe قَدَّسَ (Forma II intensiva) refleja con precisión esta fuerza declarativo-causativa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131234, 'spa', 'santificarse (Hitpael reflexivo)', 'El Hitpael reflexivo coloca la carga de la consagración sobre el propio sujeto: ''santificaos'' (Lv 11:44, Jos 3:5). La preparación para la teofanía en el Sinaí (Éx 19:22) y la entrada en Canaán exigen autopurificación. El imperativo santificaos expresa vívidamente esta llamada reflexiva a la santidad personal ante el encuentro con lo divino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131235, 'spa', 'dedicar, apartar (Hifil)', 'El Hifil causativo enfatiza el acto de dedicar personas, botín u objetos al servicio exclusivo de Dios. Levítico lo emplea para las ofrendas que se acercan (Lv 22:2-3), y Crónicas registra las dedicaciones del templo. El español consagrar y el francés dédier distinguen este matiz dedicatorio de la santificación más amplia del Piel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131239, 'spa', 'mostrarse santo (Nifal)', 'El Nifal pasivo-reflexivo describe a Dios siendo mostrado santo o vindicado como santo entre su pueblo y las naciones. En Lv 10:3, Dios declara ''seré santificado'', y Ezequiel emplea reiteradamente esta forma para la vindicación escatológica (Ez 20:41; 36:23). La santidad se manifiesta públicamente como demostración del carácter divino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131240, 'spa', 'ser/volverse santo (Qal estativo)', 'El Qal estativo describe la condición inherente de ser o volverse santo — no un acto realizado, sino un estado alcanzado. El contacto con el altar hace santas las cosas (Éx 29:37, 30:29), y la presencia misma de Dios consagra el tabernáculo (Éx 29:43). Expresa la santidad como condición resultante, no como acción.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131273, 'spa', 'ser consagrado (Pual pasivo)', 'El Pual pasivo describe el estado resultante de haber sido consagrado por la acción de otro. Los ''consagrados'' de Isaías (Is 13:3) y los sacerdotes que se mantuvieron apartados (2 Cr 26:18, Ez 48:11) ilustran personas u objetos que portan la marca de una santificación previa. El árabe مُقَدَّس (participio pasivo) refleja exactamente este perfil.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131274, 'spa', 'cosas santas, santuarios (nominal)', 'Ocasionalmente la raíz verbal funciona nominalmente para designar cosas santas o santuarios, como en 2 Cr 15:18 (objetos dedicados traídos al templo) y Ez 7:24 (santuarios profanados por invasores). Este uso nominal es infrecuente pero contextualmente claro, y tiende un puente entre el verbo y el sustantivo afín קֹדֶשׁ.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131337, 'spa', 'Cedes (nombre propio)', 'Nombre de ciudad que significa «santuario», principalmente Cedes en Neftalí — ciudad de refugio (Jos 20:7) y ciudad levítica gersonita (Jos 21:32). Patria de Barac, donde Débora lo convocó contra Sísara (Jue 4:6, 9-10). Capturada por Tiglat-pileser III (2 R 15:29). También una ciudad en Isacar (1 Cr 6:57) y otra en el sur de Judá (Jos 15:23).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131342, 'spa', 'santidad, sacralidad', 'La cualidad abstracta de santidad, sacralidad o consagración — el atributo divino mismo o el estado de estar apartado. Éx 3:5 (''el suelo que pisas es santo'') e Is 6:3 (''santo, santo, santo es el SEÑOR de los ejércitos'') muestran la santidad tanto como cualidad predicada de lugares como atributo intrínseco de Dios, la esencia de su ser trascendente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131344, 'spa', 'santuario, lugar santo', 'Santuario o lugar santo — el espacio sagrado apartado para el culto, especialmente la cámara interior del tabernáculo o el templo. Éx 26:33 (''el velo separará el lugar santo del santísimo'') y Éx 28:29 (''Aarón llevará los nombres cuando entre en el lugar santo'') definen el santuario como el espacio donde la presencia divina se localiza de modo tangible.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131346, 'spa', 'santidad (con posesivo)', 'Santidad con pronombre posesivo — su santidad, mi santidad, tu santidad — que expresa la cualidad divina o humana del apartamiento consagrado como atributo poseído. Sal 89:36 (''una vez juré por mi santidad'') y Lv 20:3 (''para profanar mi santo nombre'') muestran la santidad de Dios como posesión personal que puede ser invocada o vulnerada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131351, 'spa', 'santísimo, santo de los santos', 'La construcción superlativa קֹדֶשׁ קָדָשִׁים — ''santo de los santos'' o ''santísimo'' — que designa el santuario más interior o los objetos de máxima consagración. Éx 26:33 (''el velo entre el lugar santo y el santísimo'') y Éx 30:29 (''serán santísimos'') emplean este patrón gramatical hebreo (sustantivo + plural del mismo sustantivo) para crear un superlativo absoluto sin paralelo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131353, 'spa', 'cosa santa, ofrenda sagrada', 'Una cosa santa u ofrenda sagrada en singular — un objeto consagrado individual, don dedicado o primicia. Éx 29:6 (''la diadema santa'') y Éx 29:29 (''las vestiduras santas'') designan objetos específicos que han cruzado del ámbito común al sagrado mediante la unción o la dedicación ritual, marcando la frontera visible entre lo profano y lo consagrado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131355, 'spa', 'cosas santas, ofrendas sagradas', 'Cosas santas u ofrendas sagradas en plural — objetos consagrados, contribuciones o dones dedicados vistos colectivamente. Éx 29:37 (''todo lo que toque el altar será santísimo'') y Lv 22:15 (''no profanarán las cosas santas'') tratan estas realidades como una categoría de objetos que exigen manejo sacerdotal especial para preservar su estatuto sagrado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131453, 'spa', 'Prostituto cultual', 'Prostituto cultual masculino o funcionario del templo asociado a prácticas sexuales rituales paganas. El término aparece en la prohibición deuteronómica (Deut 23:17, ''no habrá qadesh entre los hijos de Israel''), y el historiador deuteronomista lo emplea como indicador de apostasía. Las traducciones al español oscilan entre ''prostituto sagrado'' como término académico y ''sodomita'' como traducción tradicional.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131457, 'spa', 'Cades (nombre de lugar)', 'Cades (nombre de lugar): el nombre de lugar Cades (קָדֵשׁ), un oasis en el desierto del Néguev que marca la frontera sur de Canaán. Israel acampó aquí durante el éxodo, y eventos cruciales ocurrieron en este sitio: el envío de los espías (Nm 13:26), la rebelión en Meriba (Nm 20:1-13) y las fallidas negociaciones con Edom (Nm 20:14-16). Ezequiel lo usa para demarcar la frontera futura ideal (Ez 47:19; 48:28). El Salmo 29:8 habla del desierto de Cades.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131463, 'spa', 'Cades-Barnea', 'Cades-Barnea, oasis principal y campamento en el desierto, ubicado en el noreste del Sinaí o el sur del Néguev, cerca de la frontera con Edom. Sirvió como base desde la cual partieron los doce espías (Nm 13:26; 32:8) y donde Israel acampó por un periodo prolongado tras la invasión fallida (Dt 1:46). Aparece en las descripciones del límite sur de la tierra (Nm 34:4; Dt 1:2, 19; Jos 15:3) y marca un hito temporal en la peregrinación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131469, 'spa', 'prostituta cultual', 'Prostituta cultual femenina asociada al culto en santuarios cananeos, distinta de la prostitución comun por su contexto religioso. En Gn 38:21-22 los vecinos preguntan por ''la prostituta del templo'' junto al camino, usando el termino como rol social reconocido. Dt 23:17 prohibe explicitamente a las mujeres israelitas servir en esta funcion. Oseas 4:14 vincula la practica con los ritos sacrificiales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131470, 'spa', 'Embotarse / dar dentera', 'Eclesiastés 10:10 advierte que «si el hierro se embota (קֵהָה) y no se afila, hay que emplear más fuerza». Jeremías 31:29-30 cita y luego refuta el proverbio sobre las uvas agrias y la dentera de los hijos (תִּקְהֶינָה). Ezequiel 18:2 cita el mismo proverbio antes de rechazarlo. En español, embotarse y dentera captan ambas acepciones del verbo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131471, 'spa', 'Hifil (causativo)', 'Hifil (causativo): convocar o reunir una asamblea -- un líder congrega activamente al pueblo. Moisés reúne a todo Israel (Éx 35:1; Nm 1:18), Aarón convoca a la congregación ante el tabernáculo (Lv 8:3; Nm 8:9) y Salomón congrega a los ancianos para la dedicación del templo. Las señales de trompeta en Nm 10:7 distinguen entre convocar y dar alarma.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131472, 'spa', 'Nifal (reflexivo/pasivo)', 'Nifal (reflexivo/pasivo): reunirse, congregarse como cuerpo -- el pueblo se junta sin convocatoria explícita o en respuesta a una crisis. En Éx 32:1 el pueblo se congrega contra Aarón exigiendo dioses, y en Nm 16:3 la facción de Coré se reúne contra Moisés. Pero la misma forma aparece positivamente en Jos 18:1, donde todo Israel se congrega en Siló. El reflexivo español ''se congregaron'' captura con precisión la voz media del Nifal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131493, 'spa', 'asamblea o congregación', 'La asamblea formalmente convocada o congregación, especialmente la comunidad reunida de Israel para el culto religioso, procedimientos legales o decisiones cívicas (Lv 4:13-14; Dt 23:2-9; Neh 8:2). La ''congregación de Yahvé'' (Nm 16:3; 20:4) subraya su carácter pactual y sacral. Este sentido abarca la reunión deliberada y organizada con propósito litúrgico o jurídico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131507, 'spa', 'multitud o tropel', 'Una multitud, compañía o tropel hostil reunido sin connotaciones específicamente religiosas — ejércitos confederados, hordas invasoras o naciones congregadas. Ezequiel privilegia este sentido para la coalición de Gog (Ez 38:4, 15) y las huestes extranjeras (Ez 23:24; 26:7). Gn 35:11 extiende el término a una ''asamblea de naciones'' prometida a Jacob, de carácter político más que litúrgico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131524, 'spa', 'Qohélet (título funcional)', 'Qohélet: título funcional que designa al orador del libro de Eclesiastés, significando «el que convoca una asamblea» o «el que recopila dichos sapienciales». La traducción griega Ekklesiastes y el concionator de Jerónimo favorecen la lectura de «predicador/convocador», mientras que la raíz hebrea qahal (''congregar'') y la referencia a proverbios recopilados en Ecl 12:9-11 apoyan la lectura de «recopilador».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131526, 'spa', 'Nombre propio del segundo hijo de Leví y antepasado epónimo del clan coatita', 'Nombre propio del segundo hijo de Leví y antepasado epónimo del clan coatita. Las genealogías trazan la línea desde Coat a través de Amram hasta Moisés y Aarón (Éx 6:16-20; Nm 3:17-19). Los coatitas portaban los utensilios más sagrados del tabernáculo -- el arca, los altares, el candelabro -- bajo estrictas prohibiciones de tocarlos o verlos descubiertos (Nm 4:4-20). Las listas de censos y asignación de ciudades aparecen en Números y Crónicas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131532, 'spa', 'Coatita (gentilicio)', 'Coatita (gentilicio). Descendiente o miembro del clan de Coat, hijo de Leví; se emplea con el artículo como sustantivo colectivo para designar al clan entero. Aparece en los censos (Nm 26:57), en las asignaciones de servicio (Nm 4:34-37) y en las genealogías levíticas posteriores (1 Cr 6:18; 2 Cr 29:12). Los coatitas estaban encargados de transportar los objetos más sagrados, situándolos en el centro de la vida cultual de Israel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131538, 'spa', 'Instrumento de medición', 'Aparecen dos contextos: construcción del templo (1 Reyes, midiendo la vasija de bronce) y restauración profética (Jeremías, midiendo la Jerusalén restaurada). La repetición en 1 Reyes 7:23 enfatiza dimensiones precisas—el cordel midió la circunferencia. El cordel de medir de Jeremías simboliza reconstrucción y expansión. Las formas entre paréntesis y corchetes en las traducciones sugieren variantes textuales o marcas morfológicas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131539, 'spa', 'Regla, cordel de medir', 'Un cordel o regla de medir que aparece en la fórmula repetida qav laqav (''regla sobre regla'') en Isaías 28:10, 13. La frase parodia la instrucción profética de Isaías, presentándola como tediosamente repetitiva. Las traducciones multilingües apuntan a un estándar de medición, sugiriendo la imagen de una construcción incremental de la enseñanza.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131541, 'spa', 'Línea de medir', 'Cordel o línea de medición usado para construcción, agrimensura o delimitación de fronteras, empleado frecuentemente en lenguaje figurado para el juicio divino y la creación. Literalmente, describe la circunferencia del mar de bronce de Salomón (1 R 7:23; 2 Cr 4:2) y la medición visionaria de Ezequiel (Ez 47:3). Figuradamente, ''tender el cordel'' puede significar tanto edificar (Zac 1:16) como destruir (2 R 21:13; Lm 2:8; Is 34:11).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131549, 'spa', 'Vomitar, expulsar', 'Vomitar o expulsar con fuerza desde el interior. En el Código de Santidad (Lv 18:25, 28; 20:22), la tierra es personificada vomitando a sus habitantes contaminados, metáfora que equipara la polución moral con la náusea física. En Job 20:15, los impíos devuelven las riquezas engullidas. Las formas Hifil y Qal comparten este significado central.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131557, 'spa', 'Esperar a una persona, un acontecimiento o un resultado previsto con paciente pe', 'Esperar a una persona, un acontecimiento o un resultado previsto con paciente perseverancia. Este es el sentido temporal-experiencial: el tiempo transcurre y el sujeto lo soporta en anticipación. Job espera una muerte que no llega (Job 3:9; 7:2), las caravanas esperan agua (Job 6:19) y el salmista espera la palabra de Dios (Sal 25:5; 130:5).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131562, 'spa', 'Depositar esperanza confiada en alguien, especialmente en Dios, donde el énfasis', 'Depositar esperanza confiada en alguien, especialmente en Dios, donde el énfasis se desplaza de la resistencia temporal al compromiso emocional y volitivo. En Is 8:17 el profeta dice ''esperaré en él,'' y Sal 52:9 declara ''esperaré en tu nombre.'' El sentido aparece frecuentemente en contextos de aflicción donde la esperanza se convierte en un acto de fe deliberado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131567, 'spa', 'Participio Qal sustantivado', 'Participio Qal sustantivado: los que esperan, los esperanzados. Son personas caracterizadas por su postura continua de confianza expectante en Dios. Isaías 40:31 promete fuerzas renovadas a ''los que esperan en el SEÑOR,'' y Sal 37:9 los contrasta con los malhechores. La nominalización participial ''los que esperan en'' muestra una expresión cristalizada de fe perseverante.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131572, 'spa', 'Ocurrencia residual del Qal finito donde el verbo describe acechar o aguardar co', 'Ocurrencia residual del Qal finito donde el verbo describe acechar o aguardar con matices hostiles o ansiosos. En Sal 56:6 los enemigos ''acechan'' la vida del salmista, introduciendo una coloración negativa ausente en los demás sentidos. El contexto hostil (los versículos circundantes hablan de emboscadas y vigilancia) distingue este uso del sentido positivo de esperar en Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131595, 'spa', 'Reunión o congregación', 'Tres usos muestran reunión: cosmológico (aguas en Génesis), posiblemente marítimo (naves en Isaías, aunque el texto puede estar corrupto), y escatológico (naciones en Jeremías). La evidencia translingüística revela incertidumbre—algunos tratan Isaías 60:9 como ''esperar'' en lugar de ''reunir'', reflejando debate sobre si esta es la raíz de reunión o la raíz de espera/esperar. Génesis y Jeremías claramente involucran reunión espacial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131596, 'spa', 'Cordel de construcción', 'Los tres pasajes involucran medición: construcción del templo (1 Reyes) y restauración profética (Jeremías, Zacarías). La doble mención en Zacarías enfatiza la planificación activa de Dios para reconstruir Jerusalén—el cordel de medir señala construcción inminente. Las formas entre corchetes en las traducciones reflejan variaciones Ketiv-Qere y relaciones de estado constructo. El referente básico es una cuerda o soga para medir.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131597, 'spa', 'Aborrecer, sentir asco', 'Sentir profunda repugnancia, asco o aborrecimiento de sí mismo. El Qal en el Salmo 95:10 expresa el fastidio de Dios durante cuarenta años hacia una generación. El Nifal en Ezequiel es reflexivo: el pueblo se aborrecerá a sí mismo por sus propias abominaciones (Ezek 20:43; 36:31; 6:9). Los términos españoles ''fastidio'' y ''aborrecerse'' captan la naturaleza visceral e introspectiva de este disgusto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131598, 'spa', 'Contender, luchar contra', 'Contender, luchar contra o disputar (intensificación del Hitpael). El Salmo 119:158 describe un disgusto que se desborda en oposición activa contra los infieles, y el Salmo 139:21 dirige esta repugnancia combativa hacia quienes aborrecen a Dios. El español ''contender'' y el paso de la repulsión pasiva al enfrentamiento hostil marcan esta acepción como extensión semántica del sentido nuclear de asco.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131602, 'spa', 'voz de Dios', 'La voz de Dios — קוֹל יהוה — en teofanía, revelación y mandato soberano. Gn 3:8 (''el SEÑOR paseando en el huerto'') y Dt 4:12 (''oísteis la voz de palabras, pero no visteis figura alguna'') anclan este sentido en la experiencia fundacional de Israel. La construcción genitiva marca una fórmula teológica posesiva, no un sonido genérico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131603, 'spa', 'voz humana', 'La voz humana ordinaria empleada en el habla, el clamor, el canto o cualquier emisión vocal. Dt 27:14 (''los levitas proclamarán en voz alta'') y 1 S 1:13 (los labios silenciosos de Ana contrastados con su voz) ilustran el rango desde la declaración pública hasta la plegaria susurrada. Es el sentido por defecto, no marcado, presente en la mayoría de las lenguas como ''voz/voix/Stimme''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131604, 'spa', 'sonido, ruido', 'Fenómenos audibles no vocales: el sonido del agua, el viento, los carros, las alas, la molienda o la batalla. El léxico se desplaza de ''voz'' a ''sonido'', señalando contenido acústico más que comunicativo. El susurro en las copas de los árboles (2 S 5:24) y el sonido de la trompeta intensificándose (Éx 19:19) ejemplifican ruidos ambientales o instrumentales distintos del habla.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131629, 'spa', 'trueno (קוֹלוֹת)', 'Trueno — específicamente el plural קוֹלוֹת usado para los estampidos en contextos de tormenta y teofanía. La narrativa de las plagas de Éxodo (9:23-34) y el Sal 29 con su séptuple ''voz del SEÑOR'' difuminan la frontera entre el trueno natural y el poder divino. Las traducciones convergen en un término meteorológico lexicalizado: truenos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131663, 'spa', 'escucha obediente (שׁמע בְּקוֹל)', 'La voz como objeto de obediencia en la colocación שָׁמַע בְּקוֹל (oír/obedecer la voz de). Los sufijos posesivos — su voz — marcan la voz como lugar de autoridad más que como mero contenido acústico. La expresión se extiende más allá de la voz divina a padres, profetas y líderes, convirtiendo ''escuchar la voz'' en sinónimo de someterse a la voluntad del que habla.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131680, 'spa', 'noticia, rumor', 'Un informe o noticia que se propaga — la voz como rumor o nueva. Gn 45:16 registra que ''se oyó la voz (הַקֹּל נִשְׁמַע) en casa de Faraón'' de que habían venido los hermanos de José. El español voz (en el sentido de ''rumor'') confirma una extensión metonímica del sonido audible a la información transmitida, desplazamiento compartido entre lenguas semíticas e indoeuropeas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131695, 'spa', 'Qal: levantarse, alzarse', 'Alzamiento físico básico: levantarse de una posición sentada, acostada o inferior. La fórmula narrativa וַיָּקָם (''y se levantó'') aparece constantemente. Gn 22:3 tiene a Abraham levantándose temprano para el sacrificio de Isaac. Gn 4:8 relata a Caín alzándose contra Abel — el verbo de movimiento que precede a la violencia. El imperativo קוּם (''¡levántate!'') convoca a la acción en textos proféticos e históricos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131706, 'spa', 'Qal: permanecer firme, perdurar', 'Sentido estativo: mantenerse firme, perdurar, permanecer vigente. No el acto de alzarse, sino el estado de estar en pie. Gn 23:17, 20 usan קוּם para la tierra que ''queda confirmada'' como posesión de Abraham. Levítico lo emplea para valoraciones que ''permanecen'' (siguen en vigor). Se trata de lo que se alza y permanece en pie — validez, vigencia, estabilidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131717, 'spa', 'Hifil: establecer, confirmar', 'Hifil causativo-abstracto: establecer, confirmar o mantener en vigor un pacto, reino, trono o decreto. Gn 6:18 tiene a Dios estableciendo su pacto con Noé. 2 S 7:12 promete que el trono de David será establecido para siempre. Capta la fuerza solidificadora y estabilizadora — hacer que algo permanezca inconmovible.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131719, 'spa', 'Hifil: suscitar una persona', 'Hifil causativo: suscitar una persona — libertador, profeta, rey o enemigo. Gn 38:8 ordena suscitar descendencia para el hermano (deber de levirato). Jueces recorre el ciclo del SEÑOR suscitando libertadores. Am 6:14 advierte que Dios suscitará una nación contra Israel. El causativo lleva a alguien al escenario de la historia por acción divina o humana.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131726, 'spa', 'Piel: confirmar, ratificar', 'Piel intensivo: confirmar, ratificar o cumplir con esmero. Rut 4:7 explica la costumbre de ''confirmar'' cualquier transacción. Est 9:21, 29, 31 describen el establecimiento de Purim como festividad. Sal 119:28 suplica: ''fortaléceme conforme a tu palabra''. La fuerza intensiva del Piel sugiere confirmación deliberada y esforzada — no permanencia pasiva, sino sostenimiento activo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131727, 'spa', 'Qal: alzarse contra, oponerse', 'Sentido hostil del Qal: alzarse contra, oponerse. Típicamente en construcciones participiales con sufijos pronominales: קָמַי (''los que se alzan contra mí''). Éx 15:7 celebra que Dios derriba ''a los que se levantaron contra ti''. Sal 18:49 agradece la liberación de ''los que se alzan contra mí''. La postura erguida se convierte en gesto de confrontación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131742, 'spa', 'Hifil: erigir, levantar', 'Hifil para la erección física de estructuras: levantar pilares, altares, el tabernáculo. Éx 40:2, 18 ordenan a Moisés ''levantar'' el tabernáculo; Nm 7:1 marca el día en que Moisés ''erigió'' el tabernáculo. Dt 27:2 ordena levantar grandes piedras encaladas. Es el sentido constructivo concreto — hacer que algo se alce verticalmente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131757, 'spa', 'Hofal: ser levantado, erigido', 'Hofal pasivo del Hifil: ser levantado, ser establecido por un agente externo. Éx 40:17 señala el día en que el tabernáculo ''fue erigido''. 2 S 23:1 describe a David como ''exaltado en lo alto''. Jer 35:14 observa que el mandato de Jonadab ''fue cumplido''. La morfología pasiva señala que otro es quien efectúa la elevación o el establecimiento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131760, 'spa', 'Hifil: cumplir (promesa)', 'Hifil con énfasis en el cumplimiento: cumplir una promesa, palabra o juramento. Gn 9:17 marca el pacto de Dios ''que he establecido''. Nm 23:19 pregunta retóricamente si Dios habla y no cumple. 1 S 15:11 lamenta que Saúl no cumplió la palabra de Dios. Capta la realización de un compromiso verbal — hacer que una palabra dicha se convierta en realidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131794, 'spa', 'Hitpael: alzarse contra', 'Hitpael reflexivo-recíproco: alzarse contra, oponerse activamente. Job 20:27; 27:7 invocan cielo y tierra como testigos, con enemigos que se alzan. Sal 17:7; 59:1 claman por liberación de ''los que se ponen contra mí''. La morfología reflexiva (levantarse contra) enfatiza la agencia: los adversarios se posicionan activamente en hostilidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131795, 'spa', 'Qal: detenerse, cuajarse', 'Sentido físico especializado del Qal: detenerse, cuajarse, quedar inmóvil. Éx 15:8 celebra las aguas del mar que ''se detuvieron'' en un montón. 1 S 4:15 y 1 R 14:4 describen los ojos de Elí y de Ahías como ''fijos'' (rígidos, sin movimiento). Es el desplazamiento de la moción a la inmovilidad — lo que se yergue y queda quieto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131853, 'spa', 'Hifil: despertar, mover a acción', 'Hifil causativo: despertar, incitar desde el sueño o la inactividad. Gn 49:9 y Nm 24:9 emplean la metáfora de despertar al león: ¿quién se atreverá a despertarlo? Designa la acción de hacer que alguien se levante del reposo o la latencia — un causativo especializado de despertar o activar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131906, 'spa', 'Hifil causativo con objetos físicos', 'Hifil causativo con objetos físicos: erigir, levantar o alzar una estructura o monumento -- trece ocurrencias, dominadas por Daniel 3 y su relato de la imagen de oro de Nabucodonosor. El rey ''erigió'' la estatua (Dn 3:1), convocó oficiales para su ''dedicación'' (3:2-3) y exigió adoración a lo que había ''erigido.'' Dios mismo ''erige'' un reino indestructible (Dn 2:44).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131907, 'spa', 'Qal intransitivo', 'Qal intransitivo: levantarse, alzarse, entrar en acción -- ocho ocurrencias. Nabucodonosor ''se levantó apresuradamente'' de su trono al ver una cuarta figura en el horno (Dn 3:24); Darío ''se levantó al alba'' para correr al foso de los leones (Dn 6:19); Zorobabel y Jesúa ''se levantaron y comenzaron a edificar'' (Esd 5:2). En la visión profética, reinos ''se levantan'' en el escenario histórico (Dn 2:39; 7:17, 24).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131908, 'spa', 'Qal estativo', 'Qal estativo: estar de pie, permanecer erguido o presente en un lugar -- seis ocurrencias. La gran estatua ''estaba de pie'' ante Nabucodonosor en su sueño (Dn 2:31); los oficiales ''estaban de pie'' en la dedicación de la imagen (Dn 3:3); los asistentes ''estaban de pie'' ante el Anciano de Días (Dn 7:10). Las formas participiales qae''m y qayyemin indican estado continuo, no acción incipiente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131909, 'spa', 'Hofal pasivo', 'Hofal pasivo: ser levantado o puesto de pie por otro agente -- dos ocurrencias, ambas en las visiones de bestias de Daniel 7. La primera bestia ''fue levantada de la tierra y puesta de pie sobre dos pies como un hombre'' (Dn 7:4); la segunda bestia ''fue levantada de un lado'' (Dn 7:5). El sujeto es receptor de la acción, algo lo levanta sin que se identifique al agente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131919, 'spa', 'Hifil causativo con personas o instituciones', 'Hifil causativo con personas o instituciones: nombrar, establecer o constituir un cargo, un acuerdo o una persona en autoridad -- seis ocurrencias en el lenguaje administrativo de Daniel y Esdras. Darío ''puso'' a Daniel sobre todo el reino (Dn 6:1, 3); los sátrapas buscaron ''establecer'' un decreto vinculante (Dn 6:8); la reina de Belsasar recuerda que Nabucodonosor ''nombró'' a Daniel como jefe de los sabios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131924, 'spa', 'Piel intensivo', 'Piel intensivo: establecer firmemente o confirmar algo con permanencia duradera -- una sola ocurrencia en Dn 6:7 (arameo 6:8), donde los oficiales instan a Darío a ''establecer'' (qayymah) un edicto y ''firmar un documento'' que no pueda ser cambiado. Esto es más que meramente ''erigir'': es ratificar, hacer irrevocable y definitivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131931, 'spa', 'La dimensión vertical medida de un edificio, muro, columna, altar u otro objeto ', 'La dimensión vertical medida de un edificio, muro, columna, altar u otro objeto construido, apareciendo 34 veces principalmente en narraciones de construcción. Se encuentra densamente en Éxodo 25-27 (especificaciones del tabernáculo), 1 Reyes 6-7 (templo de Salomón) y Génesis 6:15 (el arca de Noé con treinta codos de altura). Funciona como término técnico arquitectónico de medición precisa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131933, 'spa', 'La altura corporal o constitución física de una persona o figura personificada, ', 'La altura corporal o constitución física de una persona o figura personificada, atestiguada 12 veces. La evidencia multilingüe revela una distinción semántica genuina: el árabe cambia a qama (estatura corporal) y el coreano a ki (altura de una persona). Pasajes clave incluyen 1 Samuel 16:7, donde Dios dice a Samuel que no juzgue por la qomah de Eliab porque el Señor mira el corazón, y Cantar de los Cantares 7:7 donde la estatura de la amada se compara a una palmera.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131949, 'spa', 'Entonar una endecha', 'Entonar una elegía fúnebre o lamento formal por los muertos o ante una destrucción inminente. Como denominativo Pi''el de qinah, este verbo denota específicamente el plañido vocalizado, a menudo ejecutado profesionalmente, en funerales o calamidades nacionales. David entona endechas sobre Saúl (2 S 1:17) y Abner (2 S 3:33); Jeremías 9:17 alude a plañideras profesionales. Ezequiel lo aplica a endechas proféticas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131958, 'spa', 'Aborrecer, sentir asco', 'Sentir profunda repugnancia, aborrecimiento o aversión hacia algo o alguien (con beth del objeto). Rebeca está hastiada de la vida por causa de sus nueras hititas (Gn 27:46); Dios aborreció a las naciones de Canaán (Lv 20:23); Israel sintió asco del maná en el desierto (Nm 21:5). Proverbios 3:11 advierte contra aborrecer la disciplina de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131959, 'spa', 'Sentir pavor angustioso', 'Sentir un pavor enfermizo o terror angustioso ante una presencia amenazante (con mippenei del objeto temido). Egipto sintió pavor ante los israelitas que se multiplicaban, y cuanto más los afligían, más se multiplicaban (Ex 1:12). Moab se angustió ante Israel (Nm 22:3). Isaías 7:16 promete que la tierra cuyos dos reyes Acaz teme será abandonada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131965, 'spa', 'Causar terror', 'Hifil causativo: causar pavor enfermizo o terror en alguien, aterrorizar. Usado en Isaías 7:6, donde la coalición siro-efraimita trama ''aterrorizar'' a Judá y abrir brecha en sus muros. Esta es la única aparición del Hifil, convirtiendo el sentimiento interior de pavor en un acto externo de intimidación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131967, 'spa', 'Despertar del sueño, usado literalmente para levantarse del reposo y figuradamen', 'Despertar del sueño, usado literalmente para levantarse del reposo y figuradamente para el despertar de los muertos a nueva vida. El español despertad/despierta y el francés s''éveiller captan la naturaleza intransitiva de este despertar. Cubre desde los compañeros de David que durmieron durante el robo de la lanza de Saúl (1 Sam 26:12) hasta la confianza del salmista ''cuando despierte, me saciaré de tu presencia'' (Sal 17:15) y el despertar escatológico de Daniel 12:2.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131975, 'spa', 'Agitarse o levantarse hacia un estado de alerta e intervención activa, usado en ', 'Agitarse o levantarse hacia un estado de alerta e intervención activa, usado en imperativos urgentes dirigidos a Dios. El inglés rouse Yourself y arouse Yourself marcan una urgencia intensificada más allá del simple despertar. En Sal 35:23 y 44:23 el salmista implora a Dios que despierte a su causa; Sal 59:5 extiende esto a un llamado al juicio contra las naciones. El antropomorfismo es deliberado y audaz — no atribuye sueño literal a Dios sino que clama por intervención divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131985, 'spa', 'Espino, zarza', 'Espinos o zarzas, usados literal y figuradamente. Introducidos en la maldición primordial (Gn 3:18, emparejados con «cardos»). En sentido práctico: riesgo de incendio (Éx 22:6), instrumento de castigo (Jue 8:7, 16). En sentido figurado: desolación (Is 32:13), trabajo estéril (Jer 12:13), maldad (2 S 23:6), enemigos que crepitan como espinos ardientes (Sal 118:12) y vecinos hostiles (Ez 28:24).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131994, 'spa', 'Cos / Hacos (nombre propio)', 'El nombre propio Qots (Cos), frecuentemente con artículo definido como Haqqots (Hacos), referido a un jefe de clan judahíta y a una familia sacerdotal. En 1 Crónicas 4:8 aparece en la genealogía de Judá. Más significativamente, Hacos encabeza el séptimo turno sacerdotal (1 Chr 24:10). Sus descendientes enfrentaron dificultades genealógicas en el período postexílico (Ezra 2:61; Neh 7:63), aunque otros participaron en la reconstrucción de las murallas (Neh 3:4, 21).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (131999, 'spa', 'Cordel o poderoso', 'Isaías 18:2 y 18:7 emplean la frase גּוֹי קַו־קָו describiendo una nación temible. La interpretación tradicional ve «poderoso, poderoso» (reduplicación enfática). Otros leen «de cordel, cordel», sugiriendo una nación que mide y conquista territorios. En español, cordel refleja la lectura de línea de medir, aunque algunas versiones optan por «poderoso».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132004, 'spa', 'Levitas llamados Coré', 'Tres referencias identifican figuras levíticas llamadas Coré: un portero (1 Crónicas 9:19, 26:1, posiblemente el mismo individuo) y un distribuidor de ofrendas (2 Crónicas 31:14, persona distinta). El rol de portero implica custodiar umbrales sagrados, mientras que el rol de distribución administra dones consagrados. Las formas entre paréntesis en alemán y francés notan variaciones morfológicas (con/sin conjunción), reflejando flexibilidad sintáctica del hebreo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132005, 'spa', 'viga estructural', 'Viga de techo o cabrio usado en la construccion de edificios. En Gn 19:8 ''mi viga'' funciona metonimicamente como el refugio de la propia casa, fundamentando la obligacion de hospitalidad. La comunidad profetica corta vigas para una nueva morada en 2 Re 6:2, 5. En 2 Cr 3:7 las vigas del templo son recubiertas de oro, y Cnt 1:17 alaba vigas de cedro en un marco pastoral.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132009, 'spa', 'Destrucción como juicio', 'Cuatro contextos presentan la destrucción como juicio: maldiciones del pacto (Deuteronomio), protección contra desastre (Salmo), advertencia profética (Isaías) y muerte personificada (Oseas). Las traducciones españolas ''destrucción'' y de ''pestilencia'' o ''destrucción'' muestran solapamiento semántico entre enfermedad y ruina. La personificación de Oseas trata la destrucción como arma del Seol, mientras que Salmo 91 la representa merodeando al mediodía.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132012, 'spa', 'Esposa de Abraham', 'Génesis 25:1 presenta a Quetura: «Abraham tomó otra mujer, cuyo nombre era Quetura». Génesis 25:4 concluye su genealogía. 1 Crónicas 1:32 la llama concubina de Abraham (פִּילֶגֶשׁ) y enumera a sus hijos. La Septuaginta la transcribe como Χεττουρα. Sus descendientes incluyen pueblos árabes como Madián y Dedán.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132014, 'spa', 'Matar, quitar la vida', 'Tres usos jobaicos y sálmicos presentan el matar en diferentes luces: la confianza de Job a pesar de amenaza mortal (13:15), la violencia predatoria del asesino impío (24:14) y la súplica del salmista por retribución divina (139:19). El español captura distinciones de tiempo (''me matará'', ''mata'', ''matarás''), siguiendo la expectación de Job, la acción habitual del asesino y el deseo del salmista. El acuerdo translingüístico confirma un significado central estable.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132015, 'spa', 'Ser muerto (pasivo)', 'La voz pasiva: ser muerto o ejecutado, expresada mediante las formas Pe''il (participio pasivo) y Hitpe''el (reflexivo-pasivo). Belsasar ''fue muerto'' (qtil, Dn 5:30) la noche de la escritura en la pared, la cuarta bestia ''fue ejecutada'' (qtilat, Dn 7:11) ante el tribunal celestial, y los sabios ''estaban siendo matados'' (mitqatlin, Dn 2:13) bajo el decreto arrasador de Nabucodonosor.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132016, 'spa', 'Matar, dar muerte', 'La voz activa: matar o dar muerte, usando el participio Pe''al y el perfecto e infinitivo Pa''el. La soberanía absoluta de Nabucodonosor se describe con el participio activo: ''a quien quería, mataba'' (qatel, Dn 5:19). El horno de fuego mata a los soldados que ejecutaron la orden del rey (qattil, Dn 3:22), y Arioc recibe órdenes ''de matar'' a los sabios (leqattalah, Dn 2:14).');